CREATE TABLE IF NOT EXISTS software_version (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name VARCHAR(255) NOT NULL,
    system_version VARCHAR(255) NOT NULL,
    system_version_alt VARCHAR(255) NOT NULL,
    link VARCHAR(1000) DEFAULT NULL,
    st VARCHAR(1000) DEFAULT NULL,
    gd VARCHAR(1000) DEFAULT NULL,
    latest BOOLEAN NOT NULL DEFAULT 0
);

